-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 11 recettes, 1 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';
    if jsonb_typeof(ph) is distinct from 'object'
       or nullif(ph->>'url', '') is null or nullif(ph->>'page', '') is null
       or nullif(ph->>'license', '') is null then
      raise exception 'Photo vérifiée obligatoire pour %', r->>'slug';
    end if;
    -- Un nouveau slug ne doit pas recréer un plat déjà importé sous un autre nom.
    if exists (
      select 1 from public.recipes existing
      where existing.id <> rid and existing.country_code = r->>'country'
        and lower(regexp_replace(regexp_replace(coalesce(existing.original_title, existing.title), '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
          = lower(regexp_replace(regexp_replace(r->>'original', '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
    ) then
      raise exception 'Doublon de plat détecté pour %', r->>'slug';
    end if;

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, coalesce(r->>'reference', ph->>'page'),
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"anguilles-au-vert","country":"BE","place":"be-flanders","original":"Anguilles au vert","title":"Anguilles au vert (paling in ’t groen)","en":"Eels in green sauce (paling in ’t groen)","es":"Anguilas en salsa verde (paling in ’t groen)","desc":"Spécialité flamande de l’Escaut : tronçons d’anguille de rivière cuits au beurre et au vin blanc dans une sauce verte d’oseille, d’épinards, de cerfeuil, de persil et d’herbes, liée au jaune d’œuf; servie avec des frites ou du pain.","cat":"Poisson","diff":"medium","prep":40,"cook":25,"serv":4,"reference":"https://fr.wikipedia.org/wiki/Anguilles_au_vert","ing":[["Anguilles dépouillées",1,"kg","en tronçons de 5 cm"],["Beurre",50,"g",null],["Échalotes",2,null,"ciselées"],["Vin blanc sec",200,"ml",null],["Oseille",100,"g",null],["Épinards",150,"g",null],["Cerfeuil, persil, estragon et sauge",1,"grand bouquet","hachés"],["Citron",1,null,"jus"],["Jaunes d’œufs",2,null,null],["Fécule de maïs",1,"c. à thé","facultatif"],["Sel et poivre",1,"c. à thé",null]],"steps":["Faire raidir les tronçons d’anguille 3 minutes dans le beurre avec les échalotes.","Mouiller avec le vin blanc et un peu d’eau à hauteur, saler, poivrer et cuire 10 minutes à frémissement.","Ajouter l’oseille, les épinards et les herbes hachés et cuire encore 5 minutes.","Hors du feu, lier la sauce avec les jaunes battus avec le jus de citron, sans faire bouillir.","Servir chaud ou froid, avec des frites ou du pain beurré."],"photo":{"file":"File:Paling in 't groen Belgie.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/d/dd/Paling_in_%27t_groen_Belgie.jpg","page":"https://commons.wikimedia.org/wiki/File:Paling_in_%27t_groen_Belgie.jpg","author":"Tasja","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}},{"slug":"croquettes-aux-crevettes","country":"BE","place":"be-flanders","original":"Croquettes aux crevettes","title":"Croquettes aux crevettes grises (garnaalkroketten)","en":"Belgian grey shrimp croquettes","es":"Croquetas de camarón gris belgas","desc":"Entrée phare de la côte belge : béchamel épaisse au fumet et au gruyère garnie de crevettes grises de la mer du Nord, refroidie, panée et frite; servie avec persil frit et citron.","cat":"Entrée","diff":"medium","prep":60,"cook":15,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Croquette_aux_crevettes","ing":[["Crevettes grises décortiquées",300,"g",null],["Beurre",80,"g",null],["Farine",100,"g",null],["Lait",250,"ml",null],["Fumet de poisson ou de crevettes",250,"ml",null],["Gruyère râpé",50,"g",null],["Jaunes d’œufs",2,null,null],["Gélatine",2,"feuilles","facultatif"],["Œufs",2,null,"pour la panure"],["Chapelure fine",150,"g",null],["Huile de friture",1,"l",null],["Persil plat et citron",1,null,"pour servir"]],"steps":["Préparer un roux avec le beurre et la farine, mouiller avec le lait et le fumet chauds et cuire 5 minutes en fouettant jusqu’à obtenir une sauce très épaisse.","Hors du feu, ajouter le fromage, les jaunes, la gélatine essorée puis les crevettes; saler, poivrer.","Étaler dans un plat filmé au contact et réfrigérer une nuit.","Façonner des cylindres, les passer dans la farine, l’œuf battu puis la chapelure, deux fois.","Frire 3 minutes à 180 °C jusqu’à ce qu’elles soient dorées; servir avec du persil frit et un quartier de citron."],"photo":{"file":"File:GarnaalKrokette1.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/b/b3/GarnaalKrokette1.JPG","page":"https://commons.wikimedia.org/wiki/File:GarnaalKrokette1.JPG","author":"AchilleT","license":"Public domain","licenseUrl":null}},{"slug":"tomate-crevettes","country":"BE","original":"Tomate-crevettes","title":"Tomate-crevettes (tomate farcie aux crevettes grises)","en":"Tomate-crevettes (tomato stuffed with grey shrimp)","es":"Tomate con camarones grises","desc":"Entrée emblématique des brasseries belges : tomate crue évidée et garnie de crevettes grises de la mer du Nord liées à la mayonnaise, servie sur un lit de salade.","cat":"Entrée","diff":"easy","prep":20,"cook":0,"serv":4,"reference":"https://fr.wikipedia.org/wiki/Tomate-crevettes","ing":[["Tomates moyennes et fermes",4,null,null],["Crevettes grises décortiquées",250,"g",null],["Mayonnaise",4,"c. à soupe",null],["Ketchup",1,"c. à thé","facultatif"],["Citron",0.5,null,"jus"],["Persil",1,"c. à soupe","haché"],["Laitue",4,"feuilles",null],["Sel et poivre",1,"pincée",null]],"steps":["Couper un chapeau aux tomates, les évider délicatement à la cuillère et les saler à l’intérieur.","Les retourner sur une grille 15 minutes pour qu’elles rendent leur eau.","Mélanger les crevettes avec la mayonnaise, le ketchup, le jus de citron et le persil.","Garnir généreusement les tomates et reposer les chapeaux.","Servir bien frais sur une feuille de laitue, avec du pain ou des frites."],"photo":{"file":"File:Tomate-crevettes.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/0/00/Tomate-crevettes.jpg","page":"https://commons.wikimedia.org/wiki/File:Tomate-crevettes.jpg","author":"Ibu","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"cramique","country":"BE","original":"Cramique","title":"Cramique (pain brioché aux raisins)","en":"Cramique (Belgian raisin brioche loaf)","es":"Cramique (pan brioche belga con pasas)","desc":"Pain brioché de Belgique et du nord de la France, riche en lait, beurre et œufs, généreusement garni de raisins secs et dégusté au petit-déjeuner tartiné de beurre.","cat":"Pain","diff":"medium","prep":30,"cook":35,"serv":10,"reference":"https://fr.wikipedia.org/wiki/Cramique","ing":[["Farine",500,"g",null],["Levure boulangère fraîche",20,"g",null],["Lait tiède",200,"ml",null],["Œufs",2,null,"plus 1 pour la dorure"],["Beurre mou",100,"g",null],["Sucre",50,"g",null],["Sel",1,"c. à thé",null],["Raisins secs",200,"g","gonflés à l’eau tiède"]],"steps":["Délayer la levure dans le lait tiède, puis pétrir avec la farine, les œufs, le sucre et le sel; incorporer le beurre peu à peu.","Ajouter les raisins égouttés en fin de pétrissage.","Laisser lever 1 h 30 jusqu’à ce que la pâte double.","Façonner un pain, le placer dans un moule à cake beurré et laisser lever 1 heure.","Dorer à l’œuf et cuire 35 minutes à 180 °C."],"photo":{"file":"File:Cramique.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/5/53/Cramique.jpg","page":"https://commons.wikimedia.org/wiki/File:Cramique.jpg","author":"Ibu","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"mitraillette","country":"BE","place":"be-brussels","original":"Mitraillette","title":"Mitraillette bruxelloise (demi-baguette, viande, frites et sauce)","en":"Mitraillette (Belgian baguette with meat, fries and sauce)","es":"Mitraillette (media baguette con carne, patatas fritas y salsa)","desc":"Sandwich des friteries de Bruxelles et de Wallonie : demi-baguette garnie d’une viande frite ou grillée — fricadelle, burger, boulettes ou mexicano — couverte de frites et d’une sauce comme l’andalouse ou la samouraï, parfois de crudités.","cat":"Cuisine de rue","diff":"easy","prep":15,"cook":15,"serv":2,"reference":"https://fr.wikipedia.org/wiki/Mitraillette_(sandwich)","ing":[["Demi-baguette",2,null,null],["Fricadelles ou steaks hachés",2,null,null],["Pommes de terre bintje",500,"g","pour les frites"],["Graisse de bœuf ou huile",1,"l",null],["Sauce andalouse ou samouraï",4,"c. à soupe",null],["Laitue, tomate et oignon",1,"poignée","facultatif"],["Sel",1,"pincée",null]],"steps":["Couper les pommes de terre en frites de 1 cm et les cuire une première fois 6 minutes à 150 °C; égoutter.","Frire ou griller la viande.","Ouvrir les demi-baguettes et les réchauffer brièvement.","Repasser les frites 2 minutes à 180 °C et les saler.","Garnir chaque pain de crudités, de viande, puis d’une grosse poignée de frites, et napper de sauce."],"photo":{"file":"File:Mitraillette (fast food).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/0/05/Mitraillette_%28fast_food%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Mitraillette_(fast_food).jpg","author":"Renatus","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}},{"slug":"gaufre-de-bruxelles","country":"BE","place":"be-brussels","original":"Gaufre de Bruxelles","title":"Gaufre de Bruxelles (gaufre rectangulaire légère et croustillante)","en":"Brussels waffle","es":"Gofre de Bruselas","desc":"Gaufre belge à pâte levée et blancs en neige, cuite dans un fer à grands carreaux profonds : rectangulaire, légère, croustillante dehors et aérienne dedans, servie au sucre glace, à la chantilly ou aux fruits.","cat":"Dessert","diff":"easy","prep":20,"cook":20,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Gaufre_de_Bruxelles","ing":[["Farine",250,"g",null],["Levure boulangère fraîche",10,"g",null],["Lait tiède",250,"ml",null],["Eau gazeuse",200,"ml",null],["Beurre fondu",100,"g",null],["Œufs",3,null,"séparés"],["Sucre vanillé",1,"sachet",null],["Sel",1,"pincée",null],["Sucre glace",2,"c. à soupe","pour servir"]],"steps":["Délayer la levure dans le lait tiède.","Mélanger la farine, le sel, le sucre vanillé, les jaunes, le lait levuré, l’eau gazeuse et le beurre fondu en une pâte lisse; laisser reposer 1 heure.","Monter les blancs en neige et les incorporer délicatement.","Cuire dans un gaufrier à gaufres de Bruxelles bien chaud et graissé, 4 à 5 minutes, jusqu’à ce qu’elles soient dorées.","Servir aussitôt saupoudrées de sucre glace, ou avec chantilly et fruits."],"photo":{"file":"File:Gaufre de Brussel.001 - Brussel.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/9/9c/Gaufre_de_Brussel.001_-_Brussel.jpg","page":"https://commons.wikimedia.org/wiki/File:Gaufre_de_Brussel.001_-_Brussel.jpg","author":"Fernando Losada Rodríguez","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"couque-de-dinant","country":"BE","place":{"slug":"be-dinant","name":"Dinant","type":"city","lat":50.2606,"lng":4.9122,"summary":"Ville wallonne sur la Meuse, connue pour ses couques moulées dans des formes en bois."},"original":"Couque de Dinant","title":"Couque de Dinant (biscuit au miel moulé)","en":"Couque de Dinant (hard honey biscuit)","es":"Couque de Dinant (galleta dura de miel)","desc":"Biscuit très dur de Dinant fait seulement de farine de froment et de miel, pressé dans des moules en bois sculpté de scènes et de motifs, et cuit à très haute température; il se déguste en petits morceaux que l’on laisse fondre en bouche.","cat":"Dessert","diff":"medium","prep":30,"cook":10,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Couque_de_Dinant","ing":[["Miel liquide",250,"g",null],["Farine de froment",250,"g",null],["Farine",30,"g","pour fariner les moules et le plan de travail"]],"steps":["Chauffer le miel jusqu’à ce qu’il soit très fluide, sans le faire bouillir.","Mélanger le miel chaud et la farine pour obtenir une pâte ferme et lisse; laisser reposer 1 heure.","Étaler la pâte sur 5 mm et la presser dans des moules en bois farinés, ou découper des formes.","Démouler sur une plaque et cuire 6 à 8 minutes à 300 °C, ou au maximum du four, jusqu’à ce qu’elle soit brun doré.","Laisser refroidir et durcir; conserver plusieurs mois dans une boîte."],"photo":{"file":"File:Couque de Dinant.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/5/5b/Couque_de_Dinant.jpg","page":"https://commons.wikimedia.org/wiki/File:Couque_de_Dinant.jpg","author":"Oreo Priest","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en"}},{"slug":"lacquemant","country":"BE","place":"be-liege","original":"Lacquemant","title":"Lacquemant liégeois (fine gaufre fourrée au sirop de candi)","en":"Lacquemant (thin Liège waffle with candi syrup)","es":"Lacquemant (gofre fino relleno de jarabe de candi)","desc":"Friandise des foires de Liège et de Gand : fine gaufrette ovale à pâte levée, fendue dans l’épaisseur et nappée d’un sirop de sucre candi parfumé à la fleur d’oranger.","cat":"Dessert","diff":"medium","prep":30,"cook":20,"serv":10,"reference":"https://fr.wikipedia.org/wiki/Lacquemant","ing":[["Farine",250,"g",null],["Levure boulangère fraîche",10,"g",null],["Lait tiède",150,"ml",null],["Œuf",1,null,null],["Beurre fondu",80,"g",null],["Sucre",20,"g",null],["Sel",1,"pincée",null],["Sucre candi brun",200,"g","pour le sirop"],["Eau",80,"ml",null],["Eau de fleur d’oranger",1,"c. à soupe",null]],"steps":["Délayer la levure dans le lait, puis mélanger avec la farine, l’œuf, le beurre, le sucre et le sel; laisser lever 1 heure.","Cuire des petites boules de pâte aplaties dans un gaufrier fin, 1 à 2 minutes.","Fendre chaque gaufrette encore chaude en deux dans l’épaisseur.","Faire fondre le sucre candi avec l’eau jusqu’à obtenir un sirop épais, puis ajouter la fleur d’oranger.","Napper l’intérieur de sirop, refermer et napper aussi le dessus; déguster tiède."],"photo":{"file":"File:Laquemant.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/2/20/Laquemant.jpg","page":"https://commons.wikimedia.org/wiki/File:Laquemant.jpg","author":"Ibu","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}},{"slug":"bouquettes-liegeoises","country":"BE","place":"be-liege","original":"Bouquettes","title":"Bouquettes liégeoises (crêpes épaisses de sarrasin aux raisins)","en":"Liège bouquettes (buckwheat pancakes with raisins)","es":"Bouquettes de Lieja (tortitas de trigo sarraceno con pasas)","desc":"Crêpes épaisses de la tradition liégeoise, servies au Nouvel An : pâte levée à la farine de sarrasin et de froment garnie de raisins secs, cuite au beurre et servie avec de la cassonade ou du sirop de Liège.","cat":"Dessert","diff":"easy","prep":20,"cook":30,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Boûkète","ing":[["Farine de sarrasin",250,"g",null],["Farine de froment",100,"g",null],["Levure boulangère fraîche",15,"g",null],["Lait tiède",500,"ml",null],["Œufs",2,null,null],["Raisins de Corinthe",150,"g",null],["Sel",1,"pincée",null],["Beurre",50,"g","pour la cuisson"],["Cassonade ou sirop de Liège",100,"g","pour servir"]],"steps":["Délayer la levure dans un peu de lait tiède.","Mélanger les farines, le sel, les œufs, le reste du lait et la levure en pâte épaisse; ajouter les raisins.","Laisser lever 1 heure au chaud.","Cuire des louches de pâte dans une poêle beurrée, 3 minutes de chaque côté, pour obtenir des crêpes épaisses.","Servir chaudes saupoudrées de cassonade ou nappées de sirop de Liège."],"photo":{"file":"File:Boûketes-rac.jpeg","url":"https://upload.wikimedia.org/wikipedia/commons/2/26/Bo%C3%BBketes-rac.jpeg","page":"https://commons.wikimedia.org/wiki/File:Bo%C3%BBketes-rac.jpeg","author":"Lucyin","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"frites-belges","country":"BE","original":"Frites belges","title":"Frites belges (double cuisson à la graisse de bœuf)","en":"Belgian fries","es":"Patatas fritas belgas","desc":"Fierté nationale belge vendue dans les friteries : bâtonnets de pommes de terre bintje cuits deux fois, de préférence dans la graisse de bœuf, servis en cornet avec mayonnaise, andalouse ou sauce samouraï.","cat":"Cuisine de rue","diff":"easy","prep":20,"cook":15,"serv":4,"reference":"https://fr.wikipedia.org/wiki/Frite","ing":[["Pommes de terre bintje",1.2,"kg",null],["Graisse de bœuf (blanc de bœuf) ou huile",2,"l",null],["Sel fin",1,"c. à thé",null],["Mayonnaise ou sauce andalouse",150,"ml","pour servir"]],"steps":["Éplucher les pommes de terre et les couper en bâtonnets de 1 cm de section.","Les rincer, puis les sécher soigneusement dans un torchon.","Première cuisson : 6 à 7 minutes à 150 °C, jusqu’à ce qu’elles soient tendres mais pâles; égoutter et laisser refroidir au moins 30 minutes.","Seconde cuisson : 2 à 3 minutes à 180 °C jusqu’à ce qu’elles soient dorées et croustillantes.","Égoutter, saler aussitôt et servir en cornet avec la sauce."],"photo":{"file":"File:Belgian fries with sauce andalouse in Brussels.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/e/e2/Belgian_fries_with_sauce_andalouse_in_Brussels.jpg","page":"https://commons.wikimedia.org/wiki/File:Belgian_fries_with_sauce_andalouse_in_Brussels.jpg","author":"CCPictureHunters WikipediaShare","license":"Public domain","licenseUrl":null}},{"slug":"pain-a-la-grecque","country":"BE","place":"be-brussels","original":"Pain à la grecque","title":"Pain à la grecque bruxellois (biscuit au sucre perlé et à la cannelle)","en":"Pain à la grecque (Brussels sugar and cinnamon biscuit)","es":"Pain à la grecque (galleta bruselense de azúcar y canela)","desc":"Biscuit allongé de Bruxelles dont le nom vient du « pain de la gracht », le fossé près duquel des moines le distribuaient : pâte levée à la cannelle et à la cassonade, roulée dans le sucre perlé et cuite jusqu’à ce qu’elle soit croquante et caramélisée.","cat":"Dessert","diff":"medium","prep":30,"cook":25,"serv":12,"reference":"https://fr.wikipedia.org/wiki/Pain_%C3%A0_la_grecque","ing":[["Farine",500,"g",null],["Levure boulangère fraîche",15,"g",null],["Lait tiède",200,"ml",null],["Beurre mou",80,"g",null],["Cassonade brune",100,"g",null],["Cannelle",2,"c. à thé",null],["Sel",1,"pincée",null],["Sucre perlé",200,"g",null]],"steps":["Délayer la levure dans le lait tiède, puis pétrir avec la farine, le beurre, la cassonade, la cannelle et le sel.","Laisser lever 1 heure.","Étaler la pâte sur 1 cm, la couper en bandes de 4 × 15 cm.","Rouler chaque bande dans le sucre perlé en pressant pour qu’il adhère.","Cuire 20 à 25 minutes à 180 °C jusqu’à ce qu’elles soient dorées et caramélisées; laisser durcir sur grille."],"photo":{"file":"File:Pain grecque.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/7/79/Pain_grecque.jpg","page":"https://commons.wikimedia.org/wiki/File:Pain_grecque.jpg","author":"Michel wal","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}}]$batch$::jsonb);
